            "content": {
              "application/json": {
                "schema": {}
              }
            }
          }
        },
        "security": [
          {
            "OpenIdConnect": []
          }
        ]
      }
    }
  },
  "components": {
    "securitySchemes": {
      "OpenIdConnect": {
        "type": "openIdConnect",
        "openIdConnectUrl": "https://localhost/auth/realms/test/.well-known/openid-configuration"
      }
    }
  }
}
```

## Under FastAPI **0.120.3**
```json
{
  "openapi": "3.1.0",
  "info": {
    "title": "My Application",
    "version": "0.1.0"
  },
  "paths": {
    "/": {
      "get": {
        "summary": "Hello World",
        "operationId": "hello_world__get",
        "responses": {
          "200": {
            "description": "Successful Response",
            "content": {
              "application/json": {
                "schema": {}
              }
            }
          }
        }
      }
    }
  }
}
```

If this behavior is expected, and I'm doing something wrong here, please let me know.

Thank you.

